def is_samepatterns(patterns, strings):
    # Mapping dictionaries to keep track of pattern-to-string and string-to-pattern mappings
    pattern_to_string = {}
    string_to_pattern = {}

    # Function to check the consistency of the mapping
    def is_consistent(pattern, string):
        if pattern in pattern_to_string and pattern_to_string[pattern] != string:
            return False
        if string in string_to_pattern and string_to_pattern[string] != pattern:
            return False
        return True

    # Function to establish the mapping
    def map_pattern_and_string(pattern, string):
        if pattern not in pattern_to_string and string not in string_to_pattern:
            pattern_to_string[pattern] = string
            string_to_pattern[string] = pattern

    # Check each pattern and string for consistency in mapping
    for pattern, string in zip(patterns, strings):
        if not is_consistent(pattern, string):
            return False
        map_pattern_and_string(pattern, string)

    return True

